    const money = (n: number) => formatMoney(n, invoice.currency);
    assert.deepEqual(out.slice(-4), [
      `Subtotal: ${money(invoice.subtotal)}`,
      `Discount: ${money(-invoice.discount)}`,
      `Tax: ${money(invoice.tax)}`,
